(function(){var btn=document.getElementById('billing-cta');if(!btn){wireCancelConfirms();return;}btn.dataset._orig=btn.textContent;function resetBtn(){btn.disabled=false;btn.textContent=btn.dataset._orig||btn.textContent;}function showAlert(msg){if(typeof alert!=='undefined')alert(msg);}function buildCashfreeUrl(sessionId){var host=(btn.getAttribute('data-cf-host')||'').trim();if(!host){host=window.location.hostname.indexOf('localhost')!==-1||window.location.hostname.indexOf('127.0.0.1')!==-1||window.location.protocol==='http:'?'https://sandbox.cashfree.com':'https://payments.cashfree.com';}return host.replace(/\/$/,'')+'/pg/subscription/'+encodeURIComponent(sessionId);}btn.addEventListener('click',async function(){btn.disabled=true;btn.textContent='Opening checkout…';try{var resp=await fetch('/dashboard/billing/subscribe',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json'},body:new FormData(),});if(!resp.ok)throw new Error('checkout-create-failed');var data=await resp.json();var sessionId=data&&data.session_id;if(!sessionId)throw new Error('missing-session-id');try{if(typeof window.fsEvent==='function'){window.fsEvent('billing_checkout_open',{provider:'cashfree',subscription_id:data.subscription_id||'',plan_id:data.plan_id||''});}}catch(e){}
window.location.href=buildCashfreeUrl(sessionId);}catch(err){resetBtn();showAlert('Could not start checkout. Refresh and try again.');}});wireCancelConfirms();function wireCancelConfirms(){var confirms=document.querySelectorAll('[data-billing-confirm]');confirms.forEach(function(b){b.addEventListener('click',function(e){var msg=b.getAttribute('data-billing-confirm');if(msg&&typeof confirm!=='undefined'&&!confirm(msg)){e.preventDefault();}});});}})();
